// Hub glance index — record JAH-GPCS-SMARTDISPLAY-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"screen_in": 8, "speaker_w": 10, "price_usd": 130};
var value = (m.screen_in*m.speaker_w/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-SMARTDISPLAY-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-SMARTDISPLAY-000001|' + value.toFixed(2) + ' glance index');

